CREATE TABLE ai_trip_previews (preview_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,job_id BIGINT NOT NULL,user_id BIGINT NOT NULL,trip_title VARCHAR(255) NULL,summary TEXT NULL,retention_status VARCHAR(20) NOT NULL,expires_at DATETIME NULL,saved_at DATETIME NULL,applied_trip_id BIGINT NULL,applied_at DATETIME NULL,version BIGINT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_ai_preview_job UNIQUE(job_id),CONSTRAINT fk_ai_preview_job FOREIGN KEY(job_id) REFERENCES ai_recommendation_jobs(job_id) ON DELETE CASCADE,CONSTRAINT fk_ai_preview_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,CONSTRAINT fk_ai_preview_applied_trip FOREIGN KEY(applied_trip_id) REFERENCES trips(trip_id) ON DELETE SET NULL,CONSTRAINT ck_ai_preview_retention CHECK(retention_status IN ('TEMPORARY','PERMANENT')));
CREATE TABLE ai_preview_hashtags (preview_id BIGINT NOT NULL,hashtag VARCHAR(10) NOT NULL,PRIMARY KEY(preview_id,hashtag),CONSTRAINT fk_ai_preview_hashtag_preview FOREIGN KEY(preview_id) REFERENCES ai_trip_previews(preview_id) ON DELETE CASCADE);
CREATE TABLE ai_preview_days (preview_day_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,preview_id BIGINT NOT NULL,day_number INT NOT NULL,CONSTRAINT uk_ai_preview_day UNIQUE(preview_id,day_number),CONSTRAINT uk_ai_preview_day_preview_pair UNIQUE(preview_id,preview_day_id),CONSTRAINT fk_ai_preview_day_preview FOREIGN KEY(preview_id) REFERENCES ai_trip_previews(preview_id) ON DELETE CASCADE);
CREATE TABLE ai_preview_places (preview_place_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,preview_id BIGINT NOT NULL,preview_day_id BIGINT NOT NULL,place_id BIGINT NOT NULL,visit_order INT NOT NULL,reason VARCHAR(100) NOT NULL,CONSTRAINT uk_ai_preview_place_global UNIQUE(preview_id,place_id),CONSTRAINT uk_ai_preview_day_order UNIQUE(preview_day_id,visit_order),CONSTRAINT fk_ai_preview_place_preview FOREIGN KEY(preview_id) REFERENCES ai_trip_previews(preview_id) ON DELETE CASCADE,CONSTRAINT fk_ai_preview_place_day FOREIGN KEY(preview_id,preview_day_id) REFERENCES ai_preview_days(preview_id,preview_day_id) ON DELETE CASCADE,CONSTRAINT fk_ai_preview_place_place FOREIGN KEY(place_id) REFERENCES places(place_id) ON DELETE RESTRICT);
CREATE INDEX idx_ai_preview_place_preview_day ON ai_preview_places(preview_id,preview_day_id);
